script:
(function () {
  'use strict';
  // Average return, two ways.
  // 1) Yearly returns r_1..r_n: arithmetic mean = sum(r) / n; geometric mean (CAGR) =
  //    (prod(1 + r))^(1/n) - 1; cumulative = prod(1 + r) - 1; standard deviation uses n - 1.
  // 2) Money-weighted return: the annual rate r that solves
  //      sum CF_i / (1 + r)^(t_i) = 0, t_i = days from start / 365,
  //    with the starting balance and deposits as outflows, withdrawals and the ending balance as
  //    inflows (spreadsheet XIRR convention), found by scanning for sign changes and bisecting.
  //    Whole-period return uses Modified Dietz: (E - B - F) / (B + sum(w_i * F_i)), w_i = (T - t_i) / T.
  // Verified (Node): returns [10%, -10%] -> arithmetic 0%, geometric -0.5013%; [50%, -50%] ->
  // geometric -13.3975%; [12, -6, 18, 4, 9] -> arithmetic 7.4%, geometric 7.0872%, cumulative 40.8276%
  // (1.12 x 0.94 x 1.18 x 1.04 x 1.09 = 1.408276), sample standard deviation 9.0443%;
  // Microsoft's Excel XIRR example (-10000 on 1/1/2008; 2750 on 3/1/2008; 4250 on 10/30/2008;
  // 3250 on 2/15/2009; 2750 on 4/1/2009) -> 37.3363%; $1,000 -> $1,100 over 365 days -> 10%;
  // Modified Dietz B=100, +50 at mid-period, E=170 -> 16%;
  // default example (10,000 on 1/1/2022, +3,000 on 1/1/2023, -1,500 on 7/1/2024, 15,500 on 12/31/2025)
  // -> 7.6563% a year, 34.2261% for the period.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var MAX_YEARS = 60, MAX_FLOWS = 30, DAY = 86400000;

  // --- calc start
  function returnStats(rets) {
    var n = rets.length, sum = 0, growth = 1, rows = [], i;
    for (i = 0; i < n; i++) {
      sum += rets[i];
      growth *= 1 + rets[i];
      rows.push({ year: i + 1, ret: rets[i], growth: growth,
        annualized: growth > 0 ? Math.pow(growth, 1 / (i + 1)) - 1 : -1 });
    }
    var arith = sum / n;
    var geo = growth > 0 ? Math.pow(growth, 1 / n) - 1 : -1;
    var sq = 0;
    for (i = 0; i < n; i++) sq += (rets[i] - arith) * (rets[i] - arith);
    return {
      n: n, arith: arith, geo: geo, cumulative: growth - 1, growth: growth,
      std: n > 1 ? Math.sqrt(sq / (n - 1)) : 0, rows: rows,
      best: Math.max.apply(null, rets), worst: Math.min.apply(null, rets)
    };
  }

  // flows: [{ t: years from start, cf: amount }]
  function presentValue(rate, flows) {
    var total = 0;
    for (var i = 0; i < flows.length; i++) total += flows[i].cf / Math.pow(1 + rate, flows[i].t);
    return total;
  }

  // Returns the root closest to 0%, or null when no rate between -99% and 1,000% a year works.
  function moneyWeightedRate(flows) {
    var grid = [], r, i;
    for (r = -0.99; r < 1; r += 0.01) grid.push(r);
    for (r = 1; r <= 10.0001; r += 0.05) grid.push(r);
    var best = null;
    function keep(x) { if (best === null || Math.abs(x) < Math.abs(best)) best = x; }
    var prevR = grid[0], prevV = presentValue(prevR, flows);
    for (i = 1; i < grid.length; i++) {
      var curR = grid[i], curV = presentValue(curR, flows);
      if (!isFinite(curV) || !isFinite(prevV)) { prevR = curR; prevV = curV; continue; }
      if (curV === 0) keep(curR);
      else if (prevV !== 0 && (prevV < 0) !== (curV < 0)) {
        var lo = prevR, hi = curR, loV = prevV;
        for (var k = 0; k < 200; k++) {
          var mid = (lo + hi) / 2, midV = presentValue(mid, flows);
          if ((midV < 0) === (loV < 0)) { lo = mid; loV = midV; } else { hi = mid; }
          if (hi - lo < 1e-12) break;
        }
        keep((lo + hi) / 2);
      }
      prevR = curR; prevV = curV;
    }
    return best;
  }

  // moves: [{ t: years from start, amount: + deposit / - withdrawal }], T = total years
  function modifiedDietz(begin, end, moves, T) {
    var net = 0, weighted = 0;
    moves.forEach(function (m) { net += m.amount; weighted += m.amount * (T - m.t) / T; });
    var base = begin + weighted;
    return base > 0 ? (end - begin - net) / base : null;
  }
  // --- calc end

  function el(id) { return document.getElementById(id); }
  function pct(x) {
    return (x * 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%';
  }
  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
    if (!m) return null;
    var t = Date.UTC(+m[1], +m[2] - 1, +m[3]);
    return isFinite(t) ? t : null;
  }
  function makeInput(id, type, extra) {
    var input = document.createElement('input');
    input.type = type;
    input.id = id;
    input.className = extra;
    return input;
  }
  function affix(text) {
    var s = document.createElement('span');
    s.className = 'input-affix';
    s.textContent = text;
    return s;
  }

  // ----- Yearly returns -----
  function yearInputs() { return Array.prototype.slice.call(document.querySelectorAll('#arRows input')); }

  function syncYearButtons() {
    var count = yearInputs().length;
    el('arAdd').disabled = count >= MAX_YEARS;
    el('arRemove').disabled = count <= 1;
  }

  function addYear() {
    var n = yearInputs().length + 1;
    if (n > MAX_YEARS) return;
    var wrap = document.createElement('div');
    wrap.className = 'flex items-center gap-3';
    var label = document.createElement('label');
    label.className = 'w-24 shrink-0 text-sm text-ink-muted';
    label.htmlFor = 'arRet' + n;
    label.textContent = 'Year ' + n;
    var group = document.createElement('div');
    group.className = 'input-group flex-1';
    var input = makeInput('arRet' + n, 'number', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    input.min = '-100';
    input.step = '0.1';
    input.setAttribute('inputmode', 'decimal');
    group.appendChild(input);
    group.appendChild(affix('%'));
    wrap.appendChild(label);
    wrap.appendChild(group);
    el('arRows').appendChild(wrap);
    syncYearButtons();
    updateYears();
    input.focus();
  }

  function removeYear() {
    var rows = el('arRows');
    if (yearInputs().length <= 1) return;
    rows.removeChild(rows.lastElementChild);
    syncYearButtons();
    updateYears();
  }

  function clearYears() {
    ['arGeo', 'arArith', 'arCum', 'arEnd', 'arCount', 'arBest', 'arWorst', 'arStd', 'arGap'].forEach(function (id) {
      el(id).textContent = '–';
    });
    el('arSchedule').innerHTML = '';
  }

  function updateYears() {
    var start = parseFloat(el('arStart').value);
    var rets = [], bad = false;
    yearInputs().forEach(function (input) {
      if (input.value.trim() === '') return;
      var v = parseFloat(input.value);
      if (!isFinite(v) || v < -100 || v > 10000) bad = true; else rets.push(v / 100);
    });
    var msg = '';
    if (isNaN(start) || start < 0 || start > 1e12) msg = 'Enter a starting amount from $0 to $1 trillion.';
    else if (bad) msg = 'Each return must be a percentage from -100% to 10,000%.';
    else if (!rets.length) msg = 'Enter at least one yearly return.';
    var error = el('arError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearYears(); return; }

    var s = returnStats(rets);
    el('arGeo').textContent = pct(s.geo);
    el('arArith').textContent = pct(s.arith);
    el('arCum').textContent = pct(s.cumulative);
    el('arEnd').textContent = money.format(start * s.growth);
    el('arCount').textContent = String(s.n);
    el('arBest').textContent = pct(s.best);
    el('arWorst').textContent = pct(s.worst);
    el('arStd').textContent = s.n > 1 ? pct(s.std) : 'Needs 2+ years';
    el('arGap').textContent = ((s.arith - s.geo) * 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' percentage points';
    el('arSchedule').innerHTML = s.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + pct(row.ret) + '</td><td>' + money.format(start * row.growth) +
             '</td><td>' + pct(row.growth - 1) + '</td><td>' + pct(row.annualized) + '</td></tr>';
    }).join('');
  }

  // ----- Money-weighted -----
  function flowRows() { return Array.prototype.slice.call(el('arMwRows').children); }

  function syncFlowButtons() {
    var count = flowRows().length;
    el('arMwAdd').disabled = count >= MAX_FLOWS;
    el('arMwRemove').disabled = count < 1;
  }

  function addFlow() {
    var n = flowRows().length + 1;
    if (n > MAX_FLOWS) return;
    var wrap = document.createElement('div');
    wrap.className = 'grid grid-cols-[minmax(0,1.25fr)_minmax(0,1fr)_minmax(0,1.25fr)] gap-2';
    var g1 = document.createElement('div');
    g1.className = 'input-group';
    var date = makeInput('arMwDate' + n, 'date', 'form-input');
    date.setAttribute('aria-label', 'Date of cash flow ' + n);
    date.value = el('arMwEndDate').value || '';
    g1.appendChild(date);
    var sel = document.createElement('select');
    sel.id = 'arMwType' + n;
    sel.className = 'form-select';
    sel.setAttribute('aria-label', 'Type of cash flow ' + n);
    [['d', 'Deposit'], ['w', 'Withdrawal']].forEach(function (o) {
      var opt = document.createElement('option');
      opt.value = o[0];
      opt.textContent = o[1];
      sel.appendChild(opt);
    });
    var g2 = document.createElement('div');
    g2.className = 'input-group';
    var amt = makeInput('arMwAmt' + n, 'number', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    amt.min = '0';
    amt.step = '100';
    amt.value = '0';
    amt.setAttribute('inputmode', 'decimal');
    amt.setAttribute('aria-label', 'Amount of cash flow ' + n);
    g2.appendChild(affix('$'));
    g2.appendChild(amt);
    wrap.appendChild(g1);
    wrap.appendChild(sel);
    wrap.appendChild(g2);
    el('arMwRows').appendChild(wrap);
    syncFlowButtons();
    updateFlows();
    date.focus();
  }

  function removeFlow() {
    var rows = el('arMwRows');
    if (!rows.lastElementChild) return;
    rows.removeChild(rows.lastElementChild);
    syncFlowButtons();
    updateFlows();
  }

  function clearFlows() {
    ['arMwRate', 'arMwPeriod', 'arMwGain', 'arMwNet', 'arMwYears', 'arMwDeposits', 'arMwWithdrawals'].forEach(function (id) {
      el(id).textContent = '–';
    });
    el('arMwNote').hidden = true;
  }

  function updateFlows() {
    var t0 = parseDate(el('arMwStartDate').value), t1 = parseDate(el('arMwEndDate').value);
    var begin = parseFloat(el('arMwStart').value), end = parseFloat(el('arMwEnd').value);
    var msg = '';
    if (t0 === null || t1 === null) msg = 'Enter a start date and an end date.';
    else if (t1 <= t0) msg = 'The end date must be after the start date.';
    else if ((t1 - t0) / DAY > 365 * 100) msg = 'Keep the period to 100 years or less.';
    else if (isNaN(begin) || begin < 0 || begin > 1e12 || isNaN(end) || end < 0 || end > 1e12) msg = 'Enter balances from $0 to $1 trillion.';
    var moves = [], deposits = 0, withdrawals = 0;
    if (!msg) {
      flowRows().forEach(function (row, i) {
        if (msg) return;
        var inputs = row.querySelectorAll('input');
        var type = row.querySelector('select').value;
        var amtText = inputs[1].value.trim();
        if (amtText === '') return;
        var amt = parseFloat(amtText);
        if (!isFinite(amt) || amt < 0 || amt > 1e12) { msg = 'Each amount must be from $0 to $1 trillion (choose Withdrawal instead of a minus sign).'; return; }
        if (amt === 0) return;
        var t = parseDate(inputs[0].value);
        if (t === null) { msg = 'Enter a date for cash flow ' + (i + 1) + '.'; return; }
        if (t < t0 || t > t1) { msg = 'Cash flow ' + (i + 1) + ' is dated outside the start and end dates.'; return; }
        var signed = type === 'w' ? -amt : amt;
        if (signed > 0) deposits += amt; else withdrawals += amt;
        moves.push({ t: (t - t0) / DAY / 365, amount: signed });
      });
    }
    if (!msg && begin + deposits <= 0) msg = 'Enter a starting balance or at least one deposit.';
    var error = el('arMwError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearFlows(); return; }

    var T = (t1 - t0) / DAY / 365;
    var flows = [{ t: 0, cf: -begin }, { t: T, cf: end }];
    moves.forEach(function (m) { flows.push({ t: m.t, cf: -m.amount }); });
    var rate = moneyWeightedRate(flows);
    var note = el('arMwNote');
    note.hidden = true;
    if (rate === null) {
      el('arMwRate').textContent = 'Not defined';
      note.textContent = 'No yearly rate between -99% and 1,000% fits these balances and cash flows. Check the amounts and dates.';
      note.hidden = false;
    } else {
      el('arMwRate').textContent = pct(rate);
      if (T < 1) {
        note.textContent = 'The period is shorter than a year, so the annualized figure projects this return over a full year. The whole-period figure shows what you actually earned.';
        note.hidden = false;
      }
    }
    var dietz = modifiedDietz(begin, end, moves, T);
    el('arMwPeriod').textContent = dietz === null ? 'Not defined' : pct(dietz);
    el('arMwGain').textContent = money.format(end - begin - (deposits - withdrawals));
    el('arMwNet').textContent = money.format(deposits - withdrawals);
    var days = Math.round((t1 - t0) / DAY);
    el('arMwYears').textContent = days.toLocaleString('en-US') + ' days (' + T.toLocaleString('en-US', { maximumFractionDigits: 2 }) + ' years)';
    el('arMwDeposits').textContent = money.format(deposits);
    el('arMwWithdrawals').textContent = money.format(withdrawals);
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('arForm');
    form.addEventListener('input', updateYears);
    form.addEventListener('change', updateYears);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('arAdd').addEventListener('click', addYear);
    el('arRemove').addEventListener('click', removeYear);
    var mw = el('arMwForm');
    mw.addEventListener('input', updateFlows);
    mw.addEventListener('change', updateFlows);
    mw.addEventListener('submit', function (e) { e.preventDefault(); });
    el('arMwAdd').addEventListener('click', addFlow);
    el('arMwRemove').addEventListener('click', removeFlow);
    syncYearButtons();
    syncFlowButtons();
    updateYears();
    updateFlows();
  });
})();
